*{box-sizing:border-box} :root{--ink:#13191b;--muted:#9ba9a4;--paper:#f0f1e9;--orange:#f17345;--mint:#a9d8bd} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101619;color:var(--paper);font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}.game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#182124}.game-shell:after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 110px #08101299;z-index:1}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:86px;padding:17px 4.1%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,#101619ed,#101619b8 72%,transparent)}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand-mark{display:grid;place-items:center;width:39px;height:39px;border:1px solid #a9d8bd77;border-radius:11px;color:var(--mint);font-family:'Barlow Condensed',sans-serif;font-size:19px;font-weight:900;letter-spacing:-1px;transform:skew(-6deg)}.brand-mark span{color:var(--orange)}.brand-name{font-family:'Barlow Condensed',sans-serif;font-size:22px;font-weight:900;line-height:.78;letter-spacing:1.6px}.brand-name>span{color:var(--orange)}.brand-name small{display:block;color:#94a19d;font:700 8px 'DM Sans',sans-serif;letter-spacing:1.5px;margin-top:7px}.race-status{display:flex;align-items:center;gap:11px;color:#a6b0ad;font-size:10px;font-weight:800;letter-spacing:1.4px}.race-status i{height:13px;border-left:1px solid #687470}.race-status b{color:#ebeee9;font-size:11px}.live-dot{height:7px;width:7px;border-radius:50%;background:#ef784e;box-shadow:0 0 11px #ef784e}.scoreboard{display:flex;align-items:center;gap:10px}.score-label{font-size:8px;font-weight:800;letter-spacing:1.3px;color:#9daaa5}.scoreboard>strong{font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1px;color:var(--mint)}.score-divider{height:24px;border-left:1px solid #66716d;margin:0 3px}.lap-label{font:700 9px 'DM Sans',sans-serif;color:#9ba9a4;letter-spacing:1px}.lap-label b{color:#fff;font-size:13px;margin-left:4px}.lap-label small{color:#78847f;font-size:9px}.mission-card{z-index:2;position:absolute;left:4.2%;top:105px;width:221px;padding:13px 15px 14px;background:#151d1fdf;border:1px solid #dae6da22;border-top:2px solid var(--orange);border-radius:8px;box-shadow:0 12px 30px #0003;backdrop-filter:blur(8px)}.mission-kicker{display:flex;align-items:center;gap:7px;color:#f28a64;font-size:8px;font-weight:800;letter-spacing:1.2px}.flag-icon{font-size:9px}.car-number{margin-left:auto;border:1px solid #d5ded635;border-radius:3px;padding:2px 6px;color:#e5e9e3;font-size:9px}.mission-main{display:flex;justify-content:space-between;align-items:center;margin-top:7px}.mission-title{font:800 27px/.9 'Barlow Condensed',sans-serif;letter-spacing:1px}.timer-wrap{text-align:right}.timer-label{display:block;color:#879590;font-size:7px;font-weight:800;letter-spacing:1px}.timer-wrap strong{font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#f5f0e2}.timer-wrap.urgent strong{color:#ff7654;animation:pulse .55s infinite alternate}@keyframes pulse{to{opacity:.55}}.needs{display:flex;gap:6px;margin-top:11px}.need-chip{display:flex;align-items:center;gap:5px;border:1px solid #fff2;border-radius:4px;padding:5px 7px;color:#adb8b1;font-size:8px;font-weight:700;letter-spacing:.5px}.need-chip .need-dot{width:5px;height:5px;border-radius:50%;background:#e8a765}.need-chip.done{color:#9ed0af;border-color:#a9d8bd44}.need-chip.done .need-dot{background:#a9d8bd}.hint-pill{position:absolute;z-index:2;left:50%;top:79%;transform:translate(-50%,-50%);display:flex;gap:8px;align-items:center;padding:8px 12px;background:#11191ddd;border:1px solid #f5f2e633;border-radius:5px;color:#f5f1e7;font-size:10px;font-weight:700;letter-spacing:.2px;white-space:nowrap;box-shadow:0 6px 20px #0003}.hint-key{display:grid;place-items:center;width:20px;height:20px;border-radius:4px;background:var(--orange);color:white;font-size:11px;font-weight:900}.toast{position:absolute;z-index:4;top:92px;left:50%;transform:translate(-50%,-10px);padding:9px 14px;border:1px solid #e8eee033;border-radius:5px;background:#11191fec;color:#f3f2e9;font-size:10px;font-weight:700;letter-spacing:.3px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-bar{position:absolute;z-index:2;left:0;right:0;bottom:0;height:67px;padding:10px 4.1%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(0deg,#101619f2,#101619c9 72%,transparent)}.crew-note{display:flex;gap:9px;align-items:center}.crew-avatar{width:30px;height:30px;display:grid;place-items:center;border:1px solid #f1734577;border-radius:50%;background:#271f1a;color:var(--orange);font-size:15px}.crew-note b{display:block;font:800 9px 'DM Sans',sans-serif;letter-spacing:1px}.crew-note small{display:block;color:#94a19d;font-size:8px;margin-top:3px}.controls-note{display:flex;gap:18px;align-items:center}.controls-note>span{display:flex;align-items:center;gap:3px}.controls-note kbd,.start-foot b{display:inline-grid;place-items:center;min-width:17px;height:17px;border:1px solid #f3f4ea3b;border-radius:3px;color:#e1e4dc;font:700 8px 'DM Sans',sans-serif;background:#ffffff0b}.controls-note small{margin-left:5px;color:#99a59f;font-size:7px;font-weight:800;letter-spacing:.7px}.sound-note{display:flex;align-items:center;gap:7px;color:#a0aba6;font-size:7px;font-weight:800;letter-spacing:1.1px}.sound-bars{height:15px;display:flex;align-items:center;gap:2px}.sound-bars i{display:block;width:2px;background:var(--mint);border-radius:2px;animation:bars .8s infinite ease-in-out alternate}.sound-bars i:nth-child(1){height:5px}.sound-bars i:nth-child(2){height:12px;animation-delay:.2s}.sound-bars i:nth-child(3){height:8px;animation-delay:.4s}.sound-bars i:nth-child(4){height:4px;animation-delay:.1s}@keyframes bars{to{height:3px}}.start-screen,.end-screen{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:linear-gradient(100deg,#111819eb 0%,#111819d9 44%,#11181930 100%);backdrop-filter:blur(2px)}.start-screen:before,.end-screen:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 49.8%,#f2eee510 50%,transparent 50.2%),repeating-linear-gradient(0deg,transparent 0 49px,#fff05 50px);opacity:.28;pointer-events:none}.start-card,.end-card{position:relative;width:min(410px,88vw);margin-right:auto;margin-left:9%;padding:27px 28px 22px;background:#151d1ff0;border:1px solid #e5eee326;border-radius:9px;box-shadow:0 24px 80px #0007}.eyebrow{display:flex;align-items:center;gap:8px;color:#a9d8bd;font-size:8px;font-weight:800;letter-spacing:1.9px}.eyebrow>span{width:6px;height:6px;border-radius:50%;background:#f17345;box-shadow:0 0 9px #f17345}.start-card h1{margin:9px 0 3px;font:900 57px/.9 'Barlow Condensed',sans-serif;letter-spacing:1.5px}.start-card h1 span{color:var(--orange)}.start-card>p{margin:12px 0 18px;color:#c0c8c0;font-size:12px;line-height:1.55}.start-instructions{display:grid;gap:10px;padding:13px 0;border-top:1px solid #d7e1d51c;border-bottom:1px solid #d7e1d51c}.start-instructions>div{display:flex;align-items:center;gap:10px;color:#cbd1c9;font-size:10px;line-height:1.45}.start-instructions b{color:#f17345;font:800 12px 'Barlow Condensed',sans-serif}.start-instructions em{color:#a9d8bd;font-style:normal;font-weight:700}.start-button{width:100%;display:flex;justify-content:space-between;align-items:center;margin-top:17px;padding:13px 15px;border:0;border-radius:4px;background:var(--orange);color:#fff;font:800 10px 'DM Sans',sans-serif;letter-spacing:1.4px;cursor:pointer;transition:background .15s,transform .15s}.start-button:hover{background:#fa8860;transform:translateY(-1px)}.start-button span{font-size:16px}.start-foot{margin-top:14px;color:#84918b;font-size:7px;font-weight:800;letter-spacing:.8px}.start-foot b{display:inline-grid;min-width:16px;height:15px;margin-left:3px;color:#dbe0d8;font-size:7px}.start-foot i{margin:0 5px;color:#65716c;font-style:normal}.start-watermark{position:absolute;right:5%;bottom:8%;color:#e9eee50c;font:900 40px 'Barlow Condensed',sans-serif;letter-spacing:5px}.end-screen{background:#101719d9}.end-card{margin:auto;width:min(390px,88vw)}.end-card h2{margin:14px 0 10px;font:900 48px/.85 'Barlow Condensed',sans-serif;letter-spacing:1px}.end-card h2 span{color:var(--orange)}.end-card>p{color:#aab5ae;font-size:12px}.final-score{display:flex;align-items:center;justify-content:space-between;margin-top:24px;padding:12px 0;border-top:1px solid #e5eee326;color:#9ca8a1;font-size:8px;font-weight:800;letter-spacing:1px}.final-score strong{color:#a9d8bd;font:800 28px 'Barlow Condensed',sans-serif}.hidden{display:none!important}.mobile-controls{display:none}.stick-zone{position:absolute;left:20px;bottom:85px;width:116px;height:116px;touch-action:none}.stick-base{position:absolute;inset:9px;border:1px solid #e7f0e530;border-radius:50%;background:#10191bbd;box-shadow:inset 0 0 24px #0004;backdrop-filter:blur(4px)}.stick-knob{position:absolute;left:50%;top:50%;width:40px;height:40px;transform:translate(-50%,-50%);border:1px solid #f2f1e765;border-radius:50%;background:#a9d8bdbd;box-shadow:0 3px 12px #0005}.stick-caption{position:absolute;left:50%;bottom:-1px;transform:translateX(-50%);font-size:7px;font-weight:800;letter-spacing:1.3px;color:#e5ede299}.action-button{position:absolute;right:22px;bottom:96px;width:76px;height:76px;border:1px solid #f7a08088;border-radius:50%;background:#e66f46dd;color:#fff;box-shadow:0 5px 22px #0007;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;font:800 8px 'DM Sans',sans-serif;letter-spacing:1px;touch-action:none}.action-icon{font-size:24px;font-weight:500;line-height:1}.action-button.pressing{transform:scale(.94);background:#f0845b}.mobile-controls.active{display:block}
@media(max-width:700px){.topbar{height:68px;padding:12px 4%}.brand-mark{width:32px;height:32px;border-radius:9px;font-size:16px}.brand{gap:8px}.brand-name{font-size:18px}.brand-name small{font-size:6px;margin-top:5px}.race-status{gap:6px;font-size:7px;letter-spacing:.8px}.race-status b{font-size:8px}.race-status i{height:10px}.scoreboard{gap:5px}.score-label{display:none}.scoreboard>strong{font-size:18px}.score-divider{height:20px;margin:0 1px}.lap-label{font-size:7px}.lap-label b{font-size:11px}.mission-card{top:78px;left:3%;width:177px;padding:9px 10px 10px}.mission-kicker{font-size:7px}.mission-main{margin-top:6px}.mission-title{font-size:22px}.timer-label{font-size:6px}.timer-wrap strong{font-size:14px}.needs{margin-top:7px;gap:4px}.need-chip{font-size:7px;padding:4px 5px;gap:4px}.need-dot{width:4px!important;height:4px!important}.bottom-bar{height:52px;padding:7px 4%}.crew-avatar{width:25px;height:25px;font-size:12px}.crew-note{gap:6px}.crew-note b{font-size:7px}.crew-note small{font-size:7px}.controls-note,.sound-note{display:none}.hint-pill{top:auto;bottom:155px;font-size:9px}.toast{top:75px;font-size:9px}.start-card,.end-card{margin:0 auto;padding:22px 22px 18px}.start-card h1{font-size:48px}.start-card>p{font-size:11px;margin:9px 0 14px}.start-instructions{gap:8px;padding:11px 0}.start-instructions>div{font-size:9px}.start-foot{font-size:6px}.mobile-controls.active{display:block}.stick-zone{left:15px;bottom:62px;width:100px;height:100px}.action-button{right:18px;bottom:72px;width:68px;height:68px}.action-icon{font-size:21px}}
@media(max-width:420px){.race-status{gap:5px}.race-status b{font-size:7px}.brand-name{font-size:16px}.mission-card{width:162px}.mission-title{font-size:20px}.scoreboard>strong{font-size:16px}.start-card{width:90vw}.start-foot{letter-spacing:.3px}.start-foot b{min-width:14px}}
